package.path='Tools/lua/?.lua;'..package.path
local json=require('ok.json')
local base='C:/portable/OpenKoikatsu/output/street-social-city-production/activity-scenes-v1'
local function read(name)local f=assert(io.open(base..'/'..name..'.json','rb'));local v=json.decode(f:read('*a'));f:close();return v end
local function write(path,s)local f=assert(io.open(path,'wb'));f:write(s);f:close()end
local function esc(s)return tostring(s):gsub('&','&amp;'):gsub('<','&lt;'):gsub('>','&gt;'):gsub('"','&quot;')end
local plan,audit,circ,renders,imports=read('plan'),read('audit'),read('circulation'),read('render'),read('import_assets')
assert(audit.status=='passed' and renders.status=='passed' and circ.status=='passed','Do not publish before native and circulation acceptance')
assert(read('art_audit').status=='passed' and read('art_install').map_sha256==audit.map_sha256,'Art revision requires an independent native reopen audit')
assert(read('art-frame-verification').status=='passed' and read('art-frame-verification').map_sha256==audit.map_sha256,'Animation must produce visible differences in native frames')
assert(audit.map_sha256==renders.map_sha256 and audit.map_sha256==read('install').map_sha256,'Screenshots and audit must match the same saved map')
assert(read('render-launcher').process_success and read('render-launcher').exit_code==0,'Final independent render must exit successfully')
local placed={};local model_count=0;for _,q in ipairs(plan.instances)do if not placed[q.asset]then placed[q.asset]=true;model_count=model_count+1 end end
local anomalies={};for _,mode in ipairs({'import_assets','art_install','art_audit','render'})do local r=read(mode..'-launcher');if not r.process_success then anomalies[#anomalies+1]={mode=mode,exit_code=r.exit_code,run_id=r.run_id}end end
local html={'<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>大學城活動場景驗收</title><style>body{background:#111c21;color:#eef3e9;font:16px/1.65 system-ui;margin:0}main{max-width:1400px;margin:auto;padding:28px}h1{margin:0}p{color:#bbcfc8}section{background:#1d2d32;border:1px solid #45645e;border-radius:12px;padding:20px;margin:20px 0}img{display:block;width:100%;border-radius:8px;margin:12px 0}a{color:#7cdcca}table{width:100%;border-collapse:collapse}td,th{padding:9px;border-bottom:1px solid #45645e;text-align:left}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(430px,1fr));gap:20px}.ok{color:#b7e9a9}</style><main><h1>大學城活動場景</h1><p>10 個場景工作包 · '..#plan.instances..' 個實際物件實例 · '..model_count..' 種實際使用模型 · 三階 LOD · 三語招牌</p><p class="ok">已重開 Unreal 正式保存地圖，完成 '..audit.checks..' 項資產與保存檢查，以及 '..#circ.corridors..' 條通路／站位掃掠。</p><p>美術修訂 v2：玫瑰大熊合照角、動態水波與噴泉水柱光效、延伸海景、384 條三維循環煙火、木質書牆與完整排練舞台。遊戲互動、NPC 動作與任務系統仍留待後續。StreetSocial.cmd 的遊戲活動未由本次新增。</p><p><a href="plan.json">場景與位置</a> · <a href="audit.json">原生驗收</a> · <a href="circulation.json">通路驗收</a> · <a href="import_assets.json">面數與來源</a> · <a href="signs.json">三語文字</a></p><section><h2>水面與美術修訂</h2><p>海灣、噴泉、魚池使用不同參數的 Single Layer Water；具有動態細波、體積吸收／散射與原生反射。海面延伸至地圖外，修正黑色遠景。煙火四組三維實例以材質時間驅動擴散、重力與閃爍；兩個時間點由原生場景實拍。一般表面保留 normal／ORM，三語文字沿用全城切換。</p><p><a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/single-layer-water-shading-model-in-unreal-engine">Epic 水面官方參考</a> · <a href="art_audit.json">美術原生驗收</a> · <a href="effects.json">煙火實例</a></p></section><section><h2>場景配置</h2><table><tr><th>場景</th><th>內容</th></tr>'}
for _,s in ipairs(plan.scenes)do html[#html+1]='<tr><td>'..esc(s.name)..'</td><td>'..esc(s.notes)..'</td></tr>'end
html[#html+1]='</table></section><div class="grid">'
for _,r in ipairs(renders.images)do html[#html+1]='<section><h2>'..esc(r.name)..'</h2><a href="renders/'..esc(r.name)..'.png"><img loading="lazy" src="renders/'..esc(r.name)..'.png"></a><p>Unreal 原生場景實拍；鏡頭與捕捉元件未保存進地圖。</p></section>'end
html[#html+1]='</div><section><h2>實際 Tripo Model 生成</h2><div class="grid"><div><img src="proof/tripo-bear.png"><a href="https://studio.tripo3d.ai/workspace/generate/1b2d400d-7850-4015-b6d8-6544e2bea201">2.8m 大熊生成工作</a></div><div><img src="proof/tripo-koi.png"><a href="https://studio.tripo3d.ai/workspace/generate/9bdffd4f-bb5b-40d5-8f0b-84c3cc0ccea1">淡水錦鯉生成工作</a></div></div><p>2K 貼圖；新有機模型經 instant-meshes-rs 後驗證。規則家具由已驗證 remesh 元件組裝，既有商品與戶外物件沿用來源收據。大熊使用有記錄的參考拓樸修復，並非宣稱原始 remesher 輸出沒有修補。</p></section><section><h2>模型三階三角形數</h2><table><tr><th>模型</th><th>LOD0 / LOD1 / LOD2</th></tr>'
local keys={};for k in pairs(imports.assets)do keys[#keys+1]=k end;table.sort(keys)
for _,id in ipairs(keys)do local r=imports.assets[id];html[#html+1]='<tr><td>'..esc(id)..'</td><td>'..table.concat(r.lod_triangles,' / ')..'</td></tr>'end
html[#html+1]='</table></section><p>原生地圖：/Game/UniversityCity/Maps/UniversityCity。語言：MPC_CityLanguage / LanguageIndex = 0 繁體、1 簡體、2 英文。</p>'
if #anomalies>0 then html[#html+1]='<section><h2>Editor 關閉診斷</h2><p>部分自動化安裝／驗收在完整關閉日誌之後仍回傳 0xC0000005 存取違例，根因尚未定位；這不是正常程序退出。場景完成狀態以另一次重開後的原生檢查及最後退出成功的渲染為準，保存地圖與全部截圖 SHA 已核對相同版本。</p><p><a href="install-launcher.json">安裝程序紀錄</a> · <a href="audit-launcher.json">驗收程序紀錄</a> · <a href="render-launcher.json">最終渲染程序紀錄</a></p></section>'end
html[#html+1]='</main></html>'
write(base..'/index.html',table.concat(html,'\n'))
write(base..'/acceptance.json',json.encode({status='passed',art_revision=read('art_install').revision,scenes=10,instances=#plan.instances,models=model_count,imported_models=#plan.models,new_tripo_models=2,firework_sparks=384,animated_scene_pairs=4,checks=audit.checks,corridors=#circ.corridors,renders=#renders.images,map_sha256=audit.map_sha256,scope=plan.scope,editor_shutdown_anomalies=anomalies}))
print('Published native activity scenes review')
